import itertools
import networkx as nx

def is_diverse(S, n):
    # S is a list of flags, each flag is a tuple of 0s and 1s
    # 0: Yellow, 1: Blue
    for color in [0, 1]:
        G = nx.Graph()
        for i, flag in enumerate(S):
            for j in range(n):
                if flag[j] == color:
                    G.add_edge(f"f{i}", f"p{j}")
        if nx.bipartite.matching.hopcroft_karp_matching(G, top_nodes=[f"f{i}" for i in range(len(S))]):
            # The matching returns a dict. The size of the matching is len(matching) // 2
            matching = nx.bipartite.matching.hopcroft_karp_matching(G, top_nodes=[f"f{i}" for i in range(len(S))])
            if len(matching) // 2 == n:
                return True
    return False

def find_M(n):
    all_flags = list(itertools.product([0, 1], repeat=n))
    for m in range(1, 2**n + 1):
        # Check if all subsets of size m are diverse
        all_diverse = True
        for S in itertools.combinations(all_flags, m):
            if not is_diverse(S, n):
                all_diverse = False
                break
        if all_diverse:
            return m
    return 2**n + 1

print(f"n=1: {find_M(1)}")
print(f"n=2: {find_M(2)}")
