import networkx as nx

def is_diverse(S, n):
    for color in [0, 1]:
        G = nx.Graph()
        edges = []
        for i, flag in enumerate(S):
            for j in range(n):
                if flag[j] == color:
                    edges.append((f"f{i}", f"p{j}"))
        G.add_edges_from(edges)
        if len(G.nodes) < 2 * n: # Not enough nodes to have a matching of size n
            if not (len(G.nodes) == 0 and n == 0): # Handle n=0 case
                pass # just continue to the next color
            else:
                continue

        # Bipartite matching
        matching = nx.bipartite.matching.hopcroft_karp_matching(G, top_nodes=[f"f{i}" for i in range(len(S))])
        if len(matching) // 2 == n:
            return True
    return False

